(29, 1, '2026-09-28 10:29:06', '2026-09-28 10:29:06', '<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"bottom\":\"50px\",\"left\":\"30px\",\"right\":\"30px\"},\"blockGap\":\"var:preset|spacing|10\"}},\"backgroundColor\":\"primary-light\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-primary-light-background-color has-background\" style=\"padding-top:50px;padding-right:30px;padding-bottom:50px;padding-left:30px\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>About PhoneTech Accessories</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"wide\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center alignwide\">Your trusted destination for modern, practical, and reliable smartphone accessories.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"bottom\":\"50px\",\"left\":\"30px\",\"right\":\"30px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:50px;padding-right:30px;padding-bottom:50px;padding-left:30px\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:image {\"id\":94,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://localhost/PhoneTech/wordpress/wp-content/uploads/2026/10/images-2.jpeg\" alt=\"\" class=\"wp-image-94\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Who We Are</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>PhoneTech Accessories is a modern online store specializing in smartphone accessories. We offer a carefully selected range of products designed to make everyday smartphone use easier, safer, and more convenient.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>From protective phone cases and fast chargers to earphones, power banks, and phone holders, we aim to provide practical products for different needs and lifestyles.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"50px\",\"bottom\":\"50px\",\"left\":\"30px\",\"right\":\"30px\"},\"blockGap\":\"var:preset|spacing|10\"}},\"backgroundColor\":\"secondary\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-secondary-background-color has-background\" style=\"padding-top:50px;padding-right:30px;padding-bottom:50px;padding-left:30px\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Our Mission</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<p class=\"has-text-align-center\">Our mission is to make quality smartphone accessories accessible and easy to find. We focus on offering practical products, clear information, and a simple shopping experience that helps customers choose the right accessories for their devices.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"25px\",\"bottom\":\"25px\",\"left\":\"20px\",\"right\":\"20px\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:25px;padding-right:20px;padding-bottom:25px;padding-left:20px\"><!-- wp:heading {\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center\"><strong>Why Choose PhoneTech?</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"style\":{\"typography\":{\"textAlign\":\"center\"},\"spacing\":{\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\"}}}} -->\n<p class=\"has-text-align-center\" style=\"padding-top:20px;padding-bottom:20px\">We focus on providing practical accessories and a simple shopping experience for every smartphone user.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Quality Products</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We select practical and reliable accessories designed for everyday smartphone use.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Wide Selection</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Discover phone cases, chargers, earphones, power banks, and holders in one place.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Modern Technology</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We keep up with the latest mobile accessories and technology trends.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Customer Support</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We aim to provide clear information and helpful support to make your shopping experience easier.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph {\"style\":{\"border\":{\"radius\":{\"topLeft\":\"12px\",\"topRight\":\"12px\",\"bottomLeft\":\"12px\",\"bottomRight\":\"12px\"}}}} -->\n<p style=\"border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-left-radius:12px;border-bottom-right-radius:12px\"></p>\n<!-- /wp:paragraph -->', 'About', '', 'publish', 'closed', 'closed', '', 'a-propos', '', '', '2026-10-02 16:04:11', '2026-10-02 16:04:11', '', 0, 'http://localhost/PhoneTech/wordpress/?page_id=29', 0, 'page', '', 0),
